fn divide(whole: { ...u, ...v }, left: { ...s }, right: { ...t }): Int
  where u disjoint s, v disjoint t =
  0;

fn route(x: { ...r }, y: { ...s }, z: { ...t }): Int
  where s disjoint t = {
  let divided = divide(x, y, z);
  let shown = show(1 + 2);
  if shown == "3" then 1 else 2
};

fn later(n: Int): Int = n + 1;

fn bad(): Int = {
  let x = later(1, 2);
  x + 1
};

